fn assert_rectangular_char_grid(rendered: &str) {
    let mut lines = rendered.lines();
    let Some(first) = lines.next() else {
        return;
    };
    let width = first.chars().count();
    for line in lines {
        assert_eq!(
            line.chars().count(),
            width,
            "rendered lines should stay aligned:\n{rendered}"
        );
    }
}

fn assert_rectangular_terminal_grid(rendered: &str) {
    let mut lines = rendered.lines();
    let Some(first) = lines.next() else {
        return;
    };
    let width = terminal_test_width(first);
    for line in lines {
        assert_eq!(
            terminal_test_width(line),
            width,
            "rendered lines should stay terminal-cell aligned:\n{rendered}"
        );
    }
}

fn assert_rectangular_terminal_grid_with_profile(
    rendered: &str,
    profile: TerminalWidthProfile,
) {
    let mut lines = rendered.lines();
    let Some(first) = lines.next() else {
        return;
    };
    let width = terminal_line_width(first, profile);
    for line in lines {
        assert_eq!(
            terminal_line_width(line, profile),
            width,
            "rendered lines should stay terminal-cell aligned:\n{rendered}"
        );
    }
}

