fn issue_53_compact_plain_and_ansi16_share_one_flowchart_geometry() {
    let input = local_semantic_input("flowchart/issue_53_long_node_labels.mmd");
    let compact = AsciiRenderOptions::ascii().with_layout_profile(AsciiLayoutProfile::Compact);
    let plain = render_flowchart(&input, &compact).expect("compact plain fixture should render");
    let ansi16 = render_flowchart(&input, &compact.with_color_mode(AsciiColorMode::Ansi16))
        .expect("compact ANSI16 fixture should render");

    assert_eq!(strip_ansi(&ansi16), plain);
    assert_rectangular_terminal_grid(&plain);
    assert_eq!(
        (
            plain
                .lines()
                .map(terminal_test_width)
                .max()
                .unwrap_or_default(),
            plain.lines().count(),
        ),
        (56, 67)
    );
}

fn flowchart_local_semantic_fixture_covers_disconnected_subgraphs() {
    let input = local_semantic_input("flowchart/disconnected_subgraphs.mmd");
    let rendered = render_flowchart(&input, &AsciiRenderOptions::ascii())
        .expect("local semantic disconnected-subgraphs flowchart fixture should render");

    for expected in [
        "Today",
        "Next Wave",
        "Today AI",
        "Today Markdown",
        "Today Reads",
        "Next AI",
        "Next Widget",
        "Next Acts",
    ] {
        assert!(
            rendered.contains(expected),
            "disconnected-subgraphs fixture should keep {expected:?} visible:\n{rendered}"
        );
    }

    assert_rectangular_char_grid(&rendered);

    let line_index = |needle: &str| first_line_index_containing(&rendered, needle);
    assert_ne!(
        line_index("Today"),
        line_index("Next Wave"),
        "disconnected subgraphs should remain separate visible groups:\n{rendered}"
    );
    assert!(
        line_index("Today AI") < line_index("Today Markdown")
            && line_index("Today Markdown") < line_index("Today Reads"),
        "an implicit isolated group under LR should use Mermaid's vertical default:\n{rendered}"
    );
    assert!(
        line_index("Next AI") < line_index("Next Widget")
            && line_index("Next Widget") < line_index("Next Acts"),
        "each implicit isolated group should use Mermaid's vertical default:\n{rendered}"
    );
}

fn compact_flowchart_route_and_group_corpus_preserves_authored_fields() {
    let cases: [(&str, &[&str]); 9] = [
        (
            "flowchart/ampersand_fanin_fanout.mmd",
            &[
                "SourceA", "SourceB", "Merge", "Fanout", "TargetA", "TargetB",
            ],
        ),
        (
            "flowchart/back_edge_labels.mmd",
            &["back to top", "back to middle"],
        ),
        (
            "flowchart/boundary_label_lane.mmd",
            &["Pipeline", "boundaryLabelWithEnoughWidth", "Success"],
        ),
        (
            "flowchart/cjk_boundary_routes.mmd",
            &["入口", "流程中枢", "校验层", "验证", "发布", "完成"],
        ),
        (
            "flowchart/disconnected_subgraphs.mmd",
            &["Today", "Today Markdown", "Next Wave", "Next Widget"],
        ),
        (
            "flowchart/multi_boundary_routes.mmd",
            &["load", "check", "Pipeline", "ok", "fail", "Retry"],
        ),
        ("flowchart/multiline_edge_label.mmd", &["north", "south"]),
        (
            "flowchart/nested_direction_boundary.mmd",
            &[
                "Outer Pipeline",
                "Inner Steps",
                "Validate",
                "Persist",
                "Done",
            ],
        ),
        (
            "flowchart/sibling_boundary_routes.mmd",
            &["Left Group", "Right Group", "Alpha", "Delta", "handoff"],
        ),
    ];
    let profiles = [
        AsciiRenderOptions::ascii(),
        AsciiRenderOptions::unicode(),
        AsciiRenderOptions::ascii().with_terminal_width_profile(TerminalWidthProfile::Cjk),
        AsciiRenderOptions::unicode().with_terminal_width_profile(TerminalWidthProfile::Cjk),
    ];

    for (fixture, expected_fields) in cases {
        let model = parse_model(&local_semantic_input(fixture));
        for options in profiles {
            let options = options.with_layout_profile(AsciiLayoutProfile::Compact);
            let rendered = render_model(&model, &options).unwrap_or_else(|error| {
                panic!("compact {fixture} render failed for {options:?}: {error}")
            });
            assert_rectangular_terminal_grid_with_profile(
                &rendered,
                options.terminal_width_profile,
            );
            for field in expected_fields {
                assert!(
                    rendered.contains(field),
                    "compact {fixture} lost authored field {field:?}:\n{rendered}"
                );
            }
        }
    }
}

fn flowchart_issue_132_edge_labels_leave_visible_line_segments() {
    for direction in ["LR", "RL"] {
        for arrow in ["-->", "<-->"] {
            for label in [
                "very long description",
                "very long descriptions",
                "很长的连接说明文字",
            ] {
                for (options, line) in [
                    (AsciiRenderOptions::ascii(), "--"),
                    (AsciiRenderOptions::unicode(), "──"),
                ] {
                    let input = format!(
                        "flowchart {direction}\nfirst {arrow}|{label}| second\nsecond --> third[many words are too much sometime]"
                    );
                    let rendered =
                        render_flowchart(&input, &options).expect("diagram should render");
                    let row = rendered
                        .lines()
                        .find(|row| row.contains(label))
                        .expect("edge label");
                    let (before, after) = row.split_once(label).expect("complete edge label");
                    assert!(
                        before.ends_with(line) && after.starts_with(line),
                        "label must leave at least two line cells on each side ({direction}, {arrow}):\n{rendered}"
                    );
                    assert_rectangular_terminal_grid(&rendered);
                }
            }
        }
    }
}

fn flowchart_node_label_wrapping_preserves_authored_breaks_and_graphemes() {
    let input = "flowchart TD\nA[\"é team 👩‍💻<br>超長標籤 abcdefghijklmnop\"] --> B[Done]";
    let options = AsciiRenderOptions::unicode().with_flowchart_node_label_wrap_width(8);
    let rendered = render_flowchart(input, &options).expect("wrapped Unicode label should render");

    for expected in [
        "é",
        "team",
        "👩‍💻",
        "超長標籤",
        "abcdefgh",
        "ijklmnop",
        "Done",
    ] {
        assert!(
            rendered.contains(expected),
            "missing complete grapheme/text fragment {expected:?}:\n{rendered}"
        );
    }
    let emoji_row = first_line_index_containing(&rendered, "👩‍💻");
    let cjk_row = first_line_index_containing(&rendered, "超長");
    assert!(
        cjk_row > emoji_row,
        "the authored <br> must remain a hard break:\n{rendered}"
    );
    assert_rectangular_terminal_grid(&rendered);
}

